import { clsx } from "clsx";
import { type LegendPayload } from "recharts";

import { ChartClasses } from "../chart.styles";
import { LegendProps, LegendEntry } from "../chart.types";

const LegendContent = ({
  payload,
  layout,
  align,
  className,
  style,
  subLabelFormatter,
  formatter,
  showIcon = true,
}: LegendProps & {
  payload: LegendEntry[];
}) => {
  if (!payload || payload.length === 0) {
    return null;
  }

  return (
    <div
      className={clsx(
        {
          [ChartClasses.legend]: true,
          [ChartClasses.legendDashboard]: layout === "dashboard",
          [ChartClasses.legendCenterAlign]: !align || align === "center",
        },
        className,
      )}
      style={style}
    >
      <ul
        className={clsx(
          {
            [ChartClasses.legendList]: true,
            [ChartClasses.legendVertical]: layout === "vertical",
            [ChartClasses.legendDashboard]: layout === "dashboard",
          },
          className,
        )}
      >
        {payload.map((entry: LegendEntry, index: number) => {
          const isLine = entry.type === "plainline" || entry.type === "line";
          // Development icon should be a dashed square in legend
          const isDashed = entry.isDashed || !!entry.strokeDasharray;
          const entryShowIcon = showIcon && entry.type !== "none";
          // Use entry.color, or entry.fill, or entry.stroke as fallback
          const iconColor = entry.color || entry.fill || entry.stroke;

          return (
            <li key={`item-${index}`} className={ChartClasses.legendItem}>
              <div style={{ display: "flex", flexDirection: "column" }}>
                <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
                  {layout === "dashboard" && (
                    <span className={ChartClasses.legendLabel}>{entry.value}</span>
                  )}
                  {entryShowIcon && (
                    <div style={{ display: "flex", alignItems: "center" }}>
                      {entry.type === "line" && !isDashed ? (
                        <span
                          className={clsx({
                            [ChartClasses.legendColor]: true,
                          })}
                          style={{
                            borderColor: iconColor,
                            borderStyle: "solid",
                            backgroundColor: iconColor,
                          }}
                        />
                      ) : (
                        <span
                          className={clsx({
                            [ChartClasses.legendColor]: true,
                            [ChartClasses.legendDashedColor]: isDashed,
                          })}
                          style={
                            isLine
                              ? {
                                  borderColor: iconColor,
                                  backgroundColor: "transparent",
                                  borderStyle: isDashed ? "dashed" : "solid",
                                  borderWidth: "2px",
                                }
                              : { backgroundColor: iconColor }
                          }
                        />
                      )}
                    </div>
                  )}
                  {layout !== "dashboard" && (
                    <span className={ChartClasses.legendLabel}>
                      {formatter
                        ? formatter(entry.value, entry as LegendPayload, index)
                        : entry.value}
                    </span>
                  )}
                </div>
                {subLabelFormatter && (
                  <span className={ChartClasses.legendSubLabel}>
                    {subLabelFormatter(entry.value, entry, index)}
                  </span>
                )}
              </div>
            </li>
          );
        })}
      </ul>
    </div>
  );
};
LegendContent.displayName = "LegendContent";

export default LegendContent;
